from pathlib import Path
from html import escape
root=Path(__file__).resolve().parents[1] / 'docs/public/images/guides';root.mkdir(parents=True,exist_ok=True)
C={'ink':'#18233b','muted':'#53627d','line':'#c8d3e6','purple':'#6954d9','blue':'#2563c6','green':'#167d69','orange':'#c96520'}
def txt(x,y,s,size=24,color='#18233b',weight=400):return f'<text x="{x}" y="{y}" font-size="{size}" fill="{color}" font-weight="{weight}">{escape(s)}</text>'
def box(x,y,w,h,fill='#ffffff',stroke='#c8d3e6',r=16):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{fill}" stroke="{stroke}" stroke-width="2"/>'
def line(x,y,X,Y,color='#6954d9',width=3,dash=''):return f'<path d="M{x} {y} L{X} {Y}" fill="none" stroke="{color}" stroke-width="{width}"'+(f' stroke-dasharray="{dash}"' if dash else '')+'/>'
def arrow(x,y,X,Y):return line(x,y,X,Y)+f'<path d="M{X-9} {Y-7} L{X} {Y} L{X-9} {Y+7}" fill="none" stroke="#6954d9" stroke-width="3"/>'
def pill(x,y,w,s,fill='#ede9fe',color='#5941bd'):return box(x,y,w,38,fill,fill,19)+txt(x+14,y+26,s,20,color,600)
def svg(name,title,subtitle,body):
 s=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 560" role="img" aria-labelledby="title desc"><title id="title">{escape(title)}</title><desc id="desc">{escape(subtitle)}。教学示意，非应用截图或录屏。</desc><rect width="960" height="560" rx="24" fill="#f5f7fc"/><g font-family="system-ui,-apple-system,PingFang SC,Microsoft YaHei,sans-serif">'+txt(36,52,title,30,weight=700)+txt(36,88,subtitle,20,C['muted'])+body+line(36,510,924,510,'#dce3ef',1)+txt(36,539,'Snow Shot · 教学示意，非应用截图 / 录屏',18,C['muted'])+'</g></svg>'
 (root/name).write_text(s)
def grid(x,y,cols,rows,cw=92,ch=52,selected=None,merged=False):
 s=''
 for r in range(rows):
  for c in range(cols):
   if merged and r==1 and c==2:continue
   wide=2*cw if merged and r==1 and c==1 else cw
   fill='#ede9fe' if selected and (r,c) in selected else ('#eaf0fa' if r==0 else '#fff')
   s+=box(x+c*cw,y+r*ch,wide,ch,fill,'#bbc8de',0)
   words=[['项目','数量','金额'],['图像','2','80'],['文字','3','60']]
   t=words[r][c] if r<len(words) and c<len(words[r]) else ''
   if merged and r==1 and c==1:
    s+=txt(x+c*cw+14,y+r*ch+23,'2',20)+txt(x+c*cw+14,y+r*ch+46,'80',20)
    continue
   s+=txt(x+c*cw+14,y+r*ch+34,t,22)
 return s
